provenance.sourcePrompt:
Newspaper front-page style outro card. 9s, 1920x1080, SILENT. Background video with sepia/aged newspaper overlay. Classic broadsheet layout — masthead, headline, body columns, date line. Echoes the opening poster card in tone but uses editorial print language instead of cinema poster language
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400&family=UnifrakturMaguntia&display=swap" rel="stylesheet">
<style>
root{
ink:#0b0d0e
ivory:#e7e0d4
oxblood:#963f43
muted:#9b948a
paper:#d4c9b0
}
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{position:relative;}
/* background video — desaturated, darkened */
#bg{
position:absolute;top:0;left:0;width:100%;height:100%
object-fit:cover;z-index:1
filter:grayscale(80%) brightness(0.45) sepia(30%)
opacity:0
}
/* paper texture overlay */
#paper-overlay{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:2
background
repeating-linear-gradient(
0deg
transparent
transparent 3px
rgba(180,160,120,0.04) 3px
rgba(180,160,120,0.04) 4px
)
radial-gradient(ellipse at center, rgba(212,201,176,0.10) 0%, rgba(11,13,14,0.55) 100%)
}
/* vignette */
#vignette{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:3
background:radial-gradient(ellipse at center, transparent 38%, rgba(0,0,0,0.72) 100%)
}
/* newspaper card — centered */
#newspaper{
position:absolute
top:50%;left:50%
transform:translate(-50%,-50%)
z-index:10
width:1100px
opacity:0
}
/* masthead — gothic/blackletter feel */
#masthead{
text-align:center
border-top:3px solid var(--ivory)
border-bottom:1px solid var(--ivory)
padding:8px 0 6px
margin-bottom:0
}
#paper-name{
font-family:'Playfair Display',Georgia,serif
font-size:22px;font-weight:400
color:var(--ivory);letter-spacing:0.45em;text-transform:uppercase
}
#date-line{
font-family:'Playfair Display',Georgia,serif
font-size:12px;font-weight:400;font-style:italic
color:var(--muted);letter-spacing:0.15em
margin-top:4px
}
/* thin rule below masthead */
#rule-masthead{
width:100%;height:3px
background:var(--ivory)
margin:6px 0 14px
opacity:0;transform-origin:left
}
/* headline */
#headline{
font-family:'Playfair Display',Georgia,serif
font-size:76px;font-weight:900
color:var(--ivory)
line-height:1.0;letter-spacing:-0.01em
text-align:center
margin-bottom:14px
opacity:0
}
/* subhead */
#subhead{
font-family:'Playfair Display',Georgia,serif
font-size:20px;font-weight:400;font-style:italic
color:rgba(231,224,212,0.78)
text-align:center;letter-spacing:0.04em
margin-bottom:16px
opacity:0
}
/* thin rule */
#rule-mid{
width:100%;height:1px
background:rgba(231,224,212,0.35)
margin-bottom:14px
opacity:0
}
/* two-column body text */
#columns{
display:flex;gap:40px
opacity:0
}
col{
flex:1
font-family:'Playfair Display',Georgia,serif
font-size:14px;font-weight:400
color:rgba(200,190,170,0.70)
line-height:1.7;letter-spacing:0.02em
text-align:justify
}
col-rule{
width:1px;background:rgba(231,224,212,0.20)
flex-shrink:0
}
/* bottom rule + tagline */
#bottom-rule{
width:100%;height:1px
background:rgba(231,224,212,0.35)
margin-top:14px
opacity:0
}
#tagline{
text-align:center;margin-top:8px
font-family:'Playfair Display',Georgia,serif
font-size:12px;font-weight:400
color:var(--oxblood);letter-spacing:0.35em;text-transform:uppercase
opacity:0
}
/* fade to black */
#fade{position:absolute;top:0;left:0;width:100%;height:100%;z-index:50;background:#000;opacity:0;pointer-events:none;}
</style>
</head>
<body>
<div id="scene">
<video id="bg" autoplay muted loop playsinline>
<source src="{{bgVid}}" type="video/mp4">
</video>
<div id="paper-overlay"></div>
<div id="vignette"></div>
<div id="fade"></div>
<div id="newspaper">
<div id="masthead">
<div id="paper-name">The Biographical Record</div>
<div id="date-line">London, England &nbsp;·&nbsp; Est. 1976 &nbsp;·&nbsp; A Life in Full</div>
</div>
<div id="rule-masthead"></div>
<div id="headline">BENEDICT<br>CUMBERBATCH</div>
<div id="subhead">From the fog of London to the dimensions of the strange — relentlessly, brilliantly human.</div>
<div id="rule-mid"></div>
<div id="columns">
<div class="col">Born into a theatrical household in Hammersmith, he walked the boards of Harrow, the corridors of RADA, and the stages of the West End before the world knew his name. Patience was his craft. The work, his answer.</div>
<div class="col-rule"></div>
<div class="col">Sherlock. Turing. Strange. Each role a different universe — each one unmistakably the same man. CBE. BAFTA. Hamlet at the Barbican, sold out in minutes. History, one life at a time.</div>
</div>
<div id="bottom-rule"></div>
<div id="tagline">History, one life at a time.</div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded', function(){
var tl = gsap.timeline()
/* bg fades in */
tl.to('#bg', {opacity:1, duration:1.0, ease:'power2.out'}, 0)
/* newspaper card slides up and fades in */
tl.to('#newspaper', {opacity:1, y:0, duration:0.75, ease:'power3.out'
startAt:{opacity:0, y:24}}, 0.5)
/* masthead rule draws left to right */
tl.to('#rule-masthead', {opacity:1, scaleX:1, duration:0.5, ease:'expo.out'
startAt:{opacity:0, scaleX:0}}, 0.7)
/* headline fades in with slight upward drift */
tl.to('#headline', {opacity:1, y:0, duration:0.65, ease:'power3.out'
startAt:{opacity:0, y:12}}, 1.0)
/* subhead */
tl.to('#subhead', {opacity:1, duration:0.5, ease:'power2.out'}, 1.55)
/* mid rule */
tl.to('#rule-mid', {opacity:1, duration:0.4, ease:'power2.out'}, 1.9)
/* columns */
tl.to('#columns', {opacity:1, y:0, duration:0.6, ease:'power2.out'
startAt:{opacity:0, y:8}}, 2.1)
/* bottom rule + tagline */
tl.to('#bottom-rule', {opacity:1, duration:0.4, ease:'power2.out'}, 2.6)
tl.to('#tagline', {opacity:1, duration:0.5, ease:'power2.out'}, 2.85)
/* hold — then exit */
tl.to('#newspaper', {opacity:0, y:-16, duration:0.65, ease:'power2.in'}, 7.0)
/* fade to black */
tl.to('#fade', {opacity:1, duration:1.6, ease:'power2.inOut'}, 7.3)
})
</script>
</body>
</html>
```
